import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.BvlN9b-o.js";const A=JSON.parse('{"title":"服务端配置","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/config","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),r={name:"reference/config.md"};function _(T,d,E,S,a,I){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="服务端配置" tabindex="-1">服务端配置 <a class="header-anchor" href="#服务端配置" aria-label="Permalink to &quot;服务端配置&quot;">​</a></h1><p>从 Rust Settings/FIELDS 自动生成。秘密字段不展示默认值；部署时由受保护配置提供。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/src/bin/config-reference.rs" target="_blank" rel="noreferrer">Settings/FIELDS</a> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/.env.example" target="_blank" rel="noreferrer">.env.example</a></p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>秘密</th><th>说明</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>受保护配置</td><td>是</td><td>PostgreSQL 连接 URL。必填；绝不写入日志。</td></tr><tr><td><code>APP_BIND</code></td><td><code>127.0.0.1:18000</code></td><td>否</td><td>API 监听 IP 地址和端口。</td></tr><tr><td><code>RUST_LOG</code></td><td><code>info</code></td><td>否</td><td>结构化日志过滤器。</td></tr><tr><td><code>MIGRATION_TIMEOUT_SECS</code></td><td><code>30</code></td><td>否</td><td>迁移执行时限，单位秒（1..3600）。</td></tr><tr><td><code>APP_ORIGIN</code></td><td><code><a href="http://127.0.0.1:15400" target="_blank" rel="noreferrer">http://127.0.0.1:15400</a></code></td><td>否</td><td>受信任的浏览器来源。除本机回环开发外必须为 HTTPS。</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td><code>604800</code></td><td>否</td><td>会话绝对有效期，单位秒（60..2592000）。</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td><code>86400</code></td><td>否</td><td>会话空闲有效期，单位秒（60..绝对有效期）。</td></tr><tr><td><code>S3_ENDPOINT</code></td><td>必需</td><td>否</td><td>内部 S3 端点（根路径）。未设置时禁用对象存储。</td></tr><tr><td><code>S3_PUBLIC_ENDPOINT</code></td><td>必需</td><td>否</td><td>浏览器可访问的 S3 来源。默认取 S3_ENDPOINT；除本机回环外必须为 HTTPS。</td></tr><tr><td><code>S3_BUCKET</code></td><td><code>saas-files</code></td><td>否</td><td>应用专用的私有存储桶。</td></tr><tr><td><code>S3_REGION</code></td><td><code>us-east-1</code></td><td>否</td><td>S3 签名区域。</td></tr><tr><td><code>S3_ACCESS_KEY</code></td><td>受保护配置</td><td>是</td><td>显式 S3 访问密钥；设置 S3_ENDPOINT 时必填。</td></tr><tr><td><code>S3_SECRET_KEY</code></td><td>受保护配置</td><td>是</td><td>显式 S3 私密密钥；启用对象存储时必填，绝不写入日志。</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td><code>20971520</code></td><td>否</td><td>文件字节上限，最终对象会再次校验（1..104857600）。</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td><code>900</code></td><td>否</td><td>上传资源/签名有效期，单位秒（1..3600）。</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td><code>60</code></td><td>否</td><td>下载能力有效期，单位秒（1..300）。撤销后停止新签名。</td></tr><tr><td><code>TELEMETRY_ENDPOINT</code></td><td>必需</td><td>否</td><td>可选的本地 OTLP/HTTP 基础 URL（回环或 collector）；留空禁用导出。</td></tr><tr><td><code>TELEMETRY_LOG_DIRECTORY</code></td><td>必需</td><td>否</td><td>可选的私有 JSON 日志目录；按小时轮转，每个服务最多保留 24 个文件。留空输出到 stdout。</td></tr><tr><td><code>TELEMETRY_QUEUE_SIZE</code></td><td><code>512</code></td><td>否</td><td>有界 span 队列（64..4096）；溢出时丢弃遥测，绝不阻塞请求。</td></tr><tr><td><code>TELEMETRY_TIMEOUT_MS</code></td><td><code>1000</code></td><td>否</td><td>OTLP 请求整体超时，单次尝试（50..2000 毫秒）。</td></tr><tr><td><code>TELEMETRY_METRICS_INTERVAL_MS</code></td><td><code>5000</code></td><td>否</td><td>指标导出间隔（1000..60000 毫秒）。</td></tr><tr><td><code>MONITORING_PROMETHEUS_URL</code></td><td>必需</td><td>否</td><td>可选的内部 Prometheus HTTP(S) 来源，仅供 API 和 Worker 查询；留空不查询指标。</td></tr><tr><td><code>MONITORING_WORKER_URL</code></td><td>必需</td><td>否</td><td>可选的内部 Worker HTTP(S) 来源，用于有时限的就绪检查。</td></tr><tr><td><code>MONITORING_GRAFANA_URL</code></td><td>必需</td><td>否</td><td>可选的浏览器可访问 Grafana URL。除回环开发外要求 HTTPS；不得嵌入凭据。</td></tr><tr><td><code>WORKER_BIND</code></td><td><code>127.0.0.1:18001</code></td><td>否</td><td>Worker 健康检查监听 IP 地址和端口。</td></tr><tr><td><code>JOB_LEASE_SECS</code></td><td><code>60</code></td><td>否</td><td>任务租约有效期（5..3600 秒）。</td></tr><tr><td><code>JOB_HEARTBEAT_SECS</code></td><td><code>20</code></td><td>否</td><td>租约续期间隔（1..租约秒数的一半）。</td></tr><tr><td><code>JOB_SHUTDOWN_SECS</code></td><td><code>10</code></td><td>否</td><td>进程退出前完成在途工作的最长时间（1..60 秒）。</td></tr><tr><td><code>JOB_MAINTENANCE_SECS</code></td><td><code>30</code></td><td>否</td><td>有界维护调度的执行间隔（1..3600 秒）。</td></tr><tr><td><code>REDIS_URL</code></td><td>受保护配置</td><td>是</td><td>可选的 redis:// 连接 URL。未设置时禁用缓存；凭据绝不写入日志。</td></tr><tr><td><code>CACHE_PREFIX</code></td><td><code>saas</code></td><td>否</td><td>部署缓存命名空间（1..100 个 ASCII 字母、数字、冒号、短横线或下划线）。</td></tr><tr><td><code>CACHE_TTL_SECS</code></td><td><code>60</code></td><td>否</td><td>正文缓存 TTL，单位秒（1..3600）。PostgreSQL 始终是授权与版本的来源。</td></tr><tr><td><code>CACHE_BUDGET_MS</code></td><td><code>100</code></td><td>否</td><td>每次读取的 Redis 总预算，含查找/回填（1..1000 毫秒）。</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td><code>true</code></td><td>否</td><td>启用注册、认证和普通请求三类限流策略。</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td><code>60</code></td><td>否</td><td>各限流策略共享的固定窗口时长（1..3600）。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td><code>20</code></td><td>否</td><td>启用 Redis 时每个 TCP 对等端/窗口的注册请求数（1..1000000）。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td><code>5</code></td><td>否</td><td>保守的本地注册容量（1..注册容量）。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td><code>60</code></td><td>否</td><td>启用 Redis 时每个 TCP 对等端/窗口的凭据请求数（1..1000000）。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td><code>20</code></td><td>否</td><td>保守的本地认证容量（1..认证容量）。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td><code>600</code></td><td>否</td><td>启用 Redis 时每个 TCP 对等端/窗口的其他请求数（1..1000000）；健康探测除外。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td><code>120</code></td><td>否</td><td>保守的本地资源容量（1..资源容量）。</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td><code>4096</code></td><td>否</td><td>本地对等端/策略桶上限（1..100000）；溢出时共享保守策略窗口。</td></tr><tr><td><code>RATE_LIMIT_PREFIX</code></td><td><code>saas</code></td><td>否</td><td>Redis 限流命名空间，与正文缓存键隔离。</td></tr><tr><td><code>RATE_LIMIT_BUDGET_MS</code></td><td><code>50</code></td><td>否</td><td>Redis 计数操作的绝对时限（1..1000 毫秒），超时回退本地。</td></tr><tr><td><code>MAIL_SMTP_HOST</code></td><td>必需</td><td>否</td><td>SMTP 主机。未设置时停发密码重置邮件；普通注册/登录不受影响。</td></tr><tr><td><code>MAIL_SMTP_PORT</code></td><td><code>1025</code></td><td>否</td><td>SMTP 端口（1..65535）；常见为 465 wrapper、587 STARTTLS、1025 本地捕获。</td></tr><tr><td><code>MAIL_SMTP_TLS</code></td><td><code>local</code></td><td>否</td><td>wrapper、starttls 或 local（仅限回环/localhost/mailpit）。</td></tr><tr><td><code>MAIL_FROM</code></td><td><code>noreply@example.test</code></td><td>否</td><td>经过校验的发件邮箱。</td></tr><tr><td><code>MAIL_SMTP_USERNAME</code></td><td>受保护配置</td><td>是</td><td>可选 SMTP 用户名；必须同时提供密码。</td></tr><tr><td><code>MAIL_SMTP_PASSWORD</code></td><td>受保护配置</td><td>是</td><td>可选 SMTP 密码；绝不写入日志。</td></tr><tr><td><code>MAIL_TIMEOUT_SECS</code></td><td><code>30</code></td><td>否</td><td>SMTP 单次尝试总时限，含 TLS/DATA/QUIT（1..300 秒）。</td></tr><tr><td><code>MAIL_ENCRYPTION_KEY</code></td><td>受保护配置</td><td>是</td><td>用于短期邮件材料的独立 32 字节十六进制密钥；API/Worker 共享，配置 SMTP 时必填。</td></tr><tr><td><code>MAIL_ENCRYPTION_KEY_VERSION</code></td><td><code>1</code></td><td>否</td><td>当前正整数密钥版本；轮换前需清空或等待旧材料过期。</td></tr><tr><td><code>PASSWORD_RESET_TTL_SECS</code></td><td><code>1800</code></td><td>否</td><td>重置链接有效期（60..3600 秒）；邮件材料不会超过链接有效期。</td></tr><tr><td><code>PASSWORD_RESET_COOLDOWN_SECS</code></td><td><code>60</code></td><td>否</td><td>合并同一账号活跃的重置请求（1..300 秒）。</td></tr><tr><td><code>EXPORT_JOB_MAX_ATTEMPTS</code></td><td><code>5</code></td><td>否</td><td>每个导出执行批次的有限尝试预算（1..20）。</td></tr><tr><td><code>EXPORT_MAX_ATTACHMENTS</code></td><td><code>100</code></td><td>否</td><td>单次文档导出的附件数量上限（0..1000）。</td></tr><tr><td><code>EXPORT_MAX_INPUT_BYTES</code></td><td><code>268435456</code></td><td>否</td><td>快照 Markdown 与附件的总字节上限（1..1073741824）。</td></tr><tr><td><code>EXPORT_MAX_OUTPUT_BYTES</code></td><td><code>285212672</code></td><td>否</td><td>ZIP 总大小上限，含文件头与中央目录（1024..1107296256）。</td></tr><tr><td><code>EXPORT_RETENTION_SECS</code></td><td><code>86400</code></td><td>否</td><td>导出结果与快照的保存期（60..604800 秒）。</td></tr><tr><td><code>EXPORT_TIMEOUT_SECS</code></td><td><code>120</code></td><td>否</td><td>导出执行的整体预算（1..600 秒），支持协作式阻塞取消。</td></tr></tbody></table><p>开发、客户端和文档发布变量有独立来源，见 <a href="./configuration-sources">变量来源分类</a>。</p>',5)])])}const O=t(r,[["render",_]]);export{A as __pageData,O as default};
